import json
import urllib.request
import urllib.error
import os

class OpenAIClient:
    \"\"\"A minimal OpenAI API client using only the Python standard library.\"\"\"

    BASE_URL = \"https://api.openai.com/v1/responses\"

    def __init__(self, api_key=None):
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise ValueError(\"API Key must be provided or set in OPENAI_API_KEY environment variable.\")

    def send_prompt(self, prompt, model=\"gpt-4o\"):
        \"\"\"Sends a text prompt to the Responses API.\"\"\"
        data = {
            \"model\": model,
            \"input\": [{\"role\": \"user\", \"content\": prompt}]
        }

        headers = {
            \"Authorization\": f\"Bearer {self.api_key}\",
            \"Content-Type\": \"application/json\"
        }

        req = urllib.request.Request(
            self.BASE_URL,
            data=json.dumps(data).encode(\"utf-8\"),
            headers=headers,
            method=\"POST\"
        )

        try:
            with urllib.request.urlopen(req) as response:
                return json.loads(response.read().decode(\"utf-8\"))
        except urllib.error.HTTPError as e:
            error_body = e.read().decode(\"utf-8\")
            raise Exception(f\"HTTP Error {e.code}: {error_body}\")
        except Exception as e:
            raise Exception(f\"Failed to send prompt: {e}\")

if __name__ == \"__main__\":
    # Example usage
    print(\"OpenAI Client module loaded.\")
EOF
